sys_script_include.script:
var ttmm = Class.create();
ttmm.prototype = {
    initialize: function() {
    },
	getUserDetails: function(userSysId) {
        var result = {};

        var gr = new GlideRecord('sys_user');
        if (gr.get(userSysId)) {
            result.sys_id = gr.getUniqueValue();
            result.name = gr.getDisplayValue('name');
            result.user_name = gr.getValue('user_name');
            result.email = gr.getValue('email');
            result.department = gr.getDisplayValue('department');
            result.manager = gr.getDisplayValue('manager');
            result.active = gr.getValue('active');
        } else {
            result.error = "User not found";
        }

        return result;
		//testing
    },


    type: 'ttmm'
};
